<?php
/** Inicializa una copia fiel de los datos DEMO del proyecto recibido (solo terminal). */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('Solo se ejecuta desde la terminal.'); }
$root = __DIR__;
$destino = $root . '/storage/torneo.db';
$existe = is_file($destino);
$restaurarPassword = in_array('--restaurar-admin', $argv ?? [], true);
$restaurarDemo = !$existe;

/** Comprueba que no haya registros de la aplicación antes de restaurar la demostración. */
function base_sin_registros(string $archivo): bool
{
    $db = new PDO('sqlite:' . $archivo, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
    $tablas = $db->query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")
                 ->fetchAll(PDO::FETCH_COLUMN);
    foreach ($tablas as $tabla) {
        if (!preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/D', $tabla)) {
            throw new RuntimeException('Nombre de tabla inesperado en SQLite.');
        }
        if ((int)$db->query('SELECT COUNT(*) FROM "' . $tabla . '"')->fetchColumn() > 0) {
            return false;
        }
    }
    return true;
}

if ($existe && !$restaurarPassword && base_sin_registros($destino)) {
    // Se puede dar el caso de que abrir la web haya creado tablas vacías antes de ejecutar el instalador.
    // Se conserva una copia antes de reemplazar SOLO una base completamente sin registros.
    $copia = $destino . '.backup_' . date('Ymd_His');
    if (!copy($destino, $copia)) {
        throw new RuntimeException('No se pudo respaldar la base SQLite vacía.');
    }
    echo "Se detectó una base sin registros. Respaldo creado: {$copia}\n";
    $restaurarDemo = true;
}

if ($existe && !$restaurarDemo) {
    require_once $root . '/app/bootstrap.php';
    $db = Database::connection();
    $email = 'admin@goolpass.com';
    $stmt = $db->prepare('SELECT id,nombre,email,rol,password FROM usuarios WHERE email = :email LIMIT 1');
    $stmt->execute([':email' => $email]);
    $admin = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$admin) {
        $db->prepare("INSERT INTO usuarios(nombre,email,password,rol) VALUES (:nombre,:email,:password,'admin')")
           ->execute([':nombre' => 'Administrador', ':email' => $email,
                      ':password' => password_hash('admin123', PASSWORD_DEFAULT)]);
        echo "Administrador de demostración restaurado sin borrar registros existentes.\n";
    } elseif ($restaurarPassword) {
        $db->prepare("UPDATE usuarios SET rol='admin', password=:password WHERE id=:id")
           ->execute([':password' => password_hash('admin123', PASSWORD_DEFAULT), ':id' => $admin['id']]);
        echo "Se restablecieron rol y contraseña del administrador de demostración.\n";
    } elseif ($admin['rol'] !== 'admin') {
        $db->prepare("UPDATE usuarios SET rol='admin' WHERE id=:id")
           ->execute([':id' => $admin['id']]);
        echo "Se restauró el rol de administrador sin cambiar su contraseña.\n";
    } else {
        echo "El usuario administrador ya existe. No se han cambiado sus datos.\n";
    }
    echo "Correo: admin@goolpass.com\n";
    echo "Contraseña de demo original: admin123 (si fue cambiada, usa: php seed.php --restaurar-admin)\n";
    exit(0);
}

function recuperar_demo(string $data): string {
    $result = gzuncompress(base64_decode($data, true));
    if ($result === false) throw new RuntimeException('Datos de demostración corruptos.');
    return $result;
}
// Copia comprimida del archivo SQLite original del usuario: 8 equipos, 88 jugadores, 3 partidos, 2 cuentas de demostración.
$demoDB = '';
if ($restaurarDemo && file_put_contents($destino, recuperar_demo($demoDB), LOCK_EX) === false) {
    throw new RuntimeException('No fue posible crear la base en storage/.');
}
// En el RAR original había 8 escudos demo. Se restauran sin alterar el resto de public/uploads/.
$images = [
    'demo_escudo_1.png' => '',
    'demo_escudo_2.png' => '',
    'demo_escudo_3.png' => '',
    'demo_escudo_4.png' => '',
    'demo_escudo_5.png' => '',
    'demo_escudo_6.png' => '',
    'demo_escudo_7.png' => '',
    'demo_escudo_8.png' => ''
];
foreach ($images as $filename => $data) {
    $path = $root . '/public/uploads/' . $filename;
    if (!file_exists($path)) file_put_contents($path, recuperar_demo($data), LOCK_EX);
}
echo "Base original restaurada: 8 equipos, 88 jugadores, 3 partidos y 2 usuarios (incluido admin).\n";
echo "Cuenta admin: admin@goolpass.com / admin123 (solo pruebas locales).\n";
echo "Inicia Apache y abre http://localhost/GoolPass/public/\n";
